WITH latest AS (SELECT id, order_id, method, amount, status FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, method ORDER BY paid_at DESC NULLS FIRST, id) AS row_num FROM payments) ranked WHERE row_num = 1) SELECT method, PERCENTILE_APPROX(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, APPROX_PERCENTILE(amount, 0.5) AS amount_p50, COUNT(*) FILTER (WHERE method = 'cash') AS cash_rows FROM latest GROUP BY method ORDER BY method;
